package com.pixarch.app.core.clip

import android.graphics.BitmapFactory
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.AfterClass
import org.junit.Assert.assertTrue
import org.junit.BeforeClass
import org.junit.Test
import org.junit.runner.RunWith

/**
 * End-to-end parity: Android preprocessing + tokenizer + the shipped INT8 ONNX models
 * versus Python (OpenCLIP preprocessing + the same ONNX files).
 * Reference: androidTest/assets/parity/, generated by scripts/make_edge_fixtures.py.
 *
 * Text goes through identical tokens and models, so it must match almost exactly.
 * Images differ only in resize filtering (Android vs PIL), so a small gap is expected.
 */
@RunWith(AndroidJUnit4::class)
class ClipParityTest {

    companion object {
        // Tokens are identical (ClipTokenizerTest); the residual is ARM vs x86 INT8 kernel
        // rounding. Measured on a Motorola Edge 40 Neo: 0.9986-0.9998.
        private const val TEXT_MIN_COSINE = 0.995f
        private const val IMAGE_MIN_COSINE = 0.97f

        private lateinit var runner: OnnxClipRunner
        private lateinit var tokenizer: ClipTokenizer

        @BeforeClass
        @JvmStatic
        fun setUp() {
            val target = InstrumentationRegistry.getInstrumentation().targetContext
            runner = OnnxClipRunner(target)
            tokenizer = ClipTokenizer(target)
        }

        @AfterClass
        @JvmStatic
        fun tearDown() = runner.close()
    }

    private val testAssets = InstrumentationRegistry.getInstrumentation().context.assets

    private data class Ref(val kind: String, val key: String, val vec: FloatArray)

    private fun refs(): List<Ref> =
        testAssets.open("parity/embeddings.tsv").bufferedReader().readLines()
            .filter { it.isNotBlank() }
            .map { line ->
                val (kind, key, vec) = line.split('\t', limit = 3)
                Ref(kind, key, vec.split(',').map { it.toFloat() }.toFloatArray())
            }

    private fun cosine(a: FloatArray, b: FloatArray): Float {
        var s = 0f
        for (i in a.indices) s += a[i] * b[i]
        return s
    }

    @Test
    fun textEmbeddingsMatchPython() {
        val report = refs().filter { it.kind == "text" }.map { ref ->
            ref.key to cosine(runner.encodeText(tokenizer.encode(ref.key)), ref.vec)
        }
        android.util.Log.i("ClipParityTest", "text parity: $report")
        assertTrue("text parity: $report", report.all { it.second >= TEXT_MIN_COSINE })
    }

    @Test
    fun imageEmbeddingsMatchPython() {
        val report = refs().filter { it.kind == "image" }.map { ref ->
            val bitmap = testAssets.open("parity/${ref.key}").use { BitmapFactory.decodeStream(it) }
            val sim = cosine(runner.encodeImage(bitmap), ref.vec)
            bitmap.recycle()
            ref.key to sim
        }
        android.util.Log.i("ClipParityTest", "image parity: $report")
        assertTrue("image parity: $report", report.all { it.second >= IMAGE_MIN_COSINE })
    }
}
